import { readHeaders } from "../src/reader";

describe("readHeaders", () => {
  it("parses header lines", () => {
    expect(readHeaders(["a: 1", "b: 2"])).toEqual([
      { name: "a", value: "1" },
      { name: "b", value: "2" },
    ]);
  });
});

